  speed: { name: 'SNABBHETSDRYCK', text: '+40 % FART I 8 S', color: '#60e060', tint: [100, 255, 120], snd: 'potion_speed' },
  ice: { name: 'ISDRYCK', text: 'FRYSER FIENDER RUNT DIG, +30 RUSTNING', color: '#70e0ff', tint: [120, 220, 255], snd: 'potion_ice' },
