  const tx = best ? best.x : P.x + Math.cos(P.a) * Math.min(10, cast(P.x, P.y, Math.cos(P.a), Math.sin(P.a)).dist - 0.1), ty = best ? best.y : P.y + Math.sin(P.a) * Math.min(10, cast(P.x, P.y, Math.cos(P.a), Math.sin(P.a)).dist - 0.1);
