  ice: { name: 'ISRUNAN', text: 'SKOTTEN SAKTAR NED OCH FRYSER IBLAND', col: '#80d0ff', tint: [128, 208, 255] },
  poison: { name: 'GIFTRUNAN', text: 'SKOTTEN FÖRGIFTAR', col: '#70e050', tint: [112, 224, 80] },
