  const wp = WEAPONS[P.weapon], lv = wlvl(wp.id), healN = Math.round(maxHp() * 0.4 * (1 + mod('campfireHeal'))), meat = run.meat || 0;
  const canRefine = window.Cards && Cards.refine && run.owned.some(id => Cards.refine(id));
