    const d = Math.hypot(e.x - P.x, e.y - P.y); if (d < (e.boss ? 9 : 4.5)) { e.stepAcc = (e.stepAcc || 0) + 1; if (e.stepAcc % (e.boss ? 6 : 5) === 0) P.shake = Math.max(P.shake, (e.boss ? 0.7 : 0.3) * (1 - d / (e.boss ? 9 : 4.5))); }
