// ---------- Faror på marken: eldpelare (varning, sedan eld) och blå eld efter Mardrömmen ----------
let hazards = [];
function addHazard(x, y, kind, o) { if (!solid(x, y)) hazards.push({ x, y, kind, t: 0, warn: o.warn, life: o.life, r: o.r, dmg: o.dmg, hitT: 0 }); }
