  if (!rec || ft < rec) { profile.bossTimes[b.id] = Math.round(ft); saveProfile(); say(`TID ${fmtTime(ft)} – NYTT REKORD!`, 4); } else say(`TID ${fmtTime(ft)} (REKORD ${fmtTime(rec)})`, 4);
