  items.push({ type: 'page', x: b.x + 0.8, y: b.y, taken: false, drop: true }); // bossens krönikesida // bättre kortval
  for (const k in doors) if (doors[k].gate) { doors[k].target = 1; play('gate', 0.8, 1, { x: doors[k].x + 0.5, y: doors[k].y + 0.5 }); }
