  if (WEAPONS[P.weapon].flame && WS.shot < 0.1) for (let r = 1; r <= 4; r++) burnThorns(P.x + Math.cos(P.a) * r, P.y + Math.sin(P.a) * r);
  for (const f of groundFires) burnThorns(f.x, f.y);
